export const getRateTicketUrl = (ticketId: number) => {
  return `/api/tickets/${ticketId}/rating`;
};

export const rateTicket = async (
  ticketId: number,
  createRatingBody: CreateRatingBody,
  options?: RequestInit,
): Promise<Rating> => {
  return customFetch<Rating>(getRateTicketUrl(ticketId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createRatingBody),
  });
};

export const getRateTicketMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof rateTicket>>,
    TError,
    { ticketId: number; data: BodyType<CreateRatingBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof rateTicket>>,
  TError,
  { ticketId: number; data: BodyType<CreateRatingBody> },
  TContext
> => {
  const mutationKey = ["rateTicket"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof rateTicket>>,
    { ticketId: number; data: BodyType<CreateRatingBody> }
  > = (props) => {
    const { ticketId, data } = props ?? {};

    return rateTicket(ticketId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

